world_checks.active_subscriptions_valid:
def check(world):
    subs = world.state().get("subscriptions", [])
    active = [s for s in subs if s.get("status") == "active"]
    if len(active) < 10:
        return f"Expected at least 10 active subscriptions, found {len(active)}"
    return None

world_checks.admin_users_exist:
def check(world):
    users = world.state().get("users", [])
    admins = [u for u in users if u.get("role") == "billing_admin"]
    if len(admins) < 10:
        return f"Expected at least 10 billing admins across tenants, found {len(admins)}"
    return None

world_checks.clock_set:
def check(world):
    clock = world.state().get("clock", [])
    if not clock or not clock[0].get("now"):
        return "World clock is missing or empty"
    return None

world_checks.plans_populated:
def check(world):
    plans = world.state().get("plans", [])
    if len(plans) < 4:
        return f"World must have at least 4 plans, found {len(plans)}"
    plan_ids = {p["plan_id"] for p in plans}
    for required_id in ["starter", "basic", "pro", "enterprise"]:
        if required_id not in plan_ids:
            return f"Missing required plan {required_id!r}"
    return None
